package tz.go.bukobamc.meetings.model;
import jakarta.persistence.*; import java.time.OffsetDateTime;
@Entity public class Invitation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) public Meeting meeting; @ManyToOne(optional=false) public Guest guest; @Column(unique=true,nullable=false) public String tokenHash; public String deliveryStatus="pending"; public String channel; public OffsetDateTime sentAt; public int remindersSent; public OffsetDateTime lastReminderAt; @OneToOne(mappedBy="invitation",cascade=CascadeType.ALL,fetch=FetchType.EAGER) public RsvpResponse response; }
